import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.B2Q7dRKp.js";const h=JSON.parse('{"title":"Tasks CSV","description":"","frontmatter":{},"headers":[],"relativePath":"guide/csv-format.md","filePath":"guide/csv-format.md","lastUpdated":1776509501000}'),r={name:"guide/csv-format.md"};function c(s,e,i,l,n,m){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tasks-csv" tabindex="-1">Tasks CSV <a class="header-anchor" href="#tasks-csv" aria-label="Permalink to &quot;Tasks CSV&quot;">​</a></h1><p>Tasks are defined in a semicolon- or comma-delimited CSV next to the exe (e.g. <code>tasks.csv</code>).</p><h2 id="sample-files" tabindex="-1">Sample files <a class="header-anchor" href="#sample-files" aria-label="Permalink to &quot;Sample files&quot;">​</a></h2><div class="download-box"><ul><li>📄 <a href="/AxgstAIO-docs/samples/tasks-buy.csv">tasks-buy.csv</a> — buy tasks across multiple sites</li><li>📄 <a href="/AxgstAIO-docs/samples/tasks-register.csv">tasks-register.csv</a> — register with address</li></ul></div><p>Right-click → Save Link As. Per-site CSVs are linked from each <a href="/AxgstAIO-docs/sites/">Site</a> page.</p><p>Samples include <strong>all</strong> supported columns; unused columns stay empty. Unknown columns are ignored, so you can keep one unified header for every CSV.</p><h2 id="required-columns" tabindex="-1">Required columns <a class="header-anchor" href="#required-columns" aria-label="Permalink to &quot;Required columns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Example</th><th>Notes</th></tr></thead><tbody><tr><td><code>site</code></td><td><code>zalando</code></td><td>Site code — see <a href="/AxgstAIO-docs/sites/">Sites</a>.</td></tr><tr><td><code>url</code></td><td><code>https://…</code> or SKU or empty</td><td>Product URL. Empty for register. SKU/keyword on sites that support search.</td></tr><tr><td><code>mode</code></td><td><code>buy</code> / <code>register</code></td><td>Task type.</td></tr><tr><td><code>qty</code></td><td><code>1</code></td><td>Quantity. Most sites respect <code>1</code> only.</td></tr><tr><td><code>max_price</code></td><td><code>3000</code></td><td>Price ceiling; task aborts above.</td></tr><tr><td><code>delay_sec</code></td><td><code>3</code></td><td>Restock probe interval.</td></tr><tr><td><code>email</code></td><td><code>you@mail.com</code></td><td>Account email.</td></tr><tr><td><code>password</code></td><td><code>P4ss!</code></td><td>Account password.</td></tr></tbody></table><h2 id="register-columns" tabindex="-1">Register columns <a class="header-anchor" href="#register-columns" aria-label="Permalink to &quot;Register columns&quot;">​</a></h2><p>Required only for <code>mode=register</code>:</p><table tabindex="0"><thead><tr><th>Column</th><th>Example</th></tr></thead><tbody><tr><td><code>first_name</code></td><td><code>Jan</code></td></tr><tr><td><code>last_name</code></td><td><code>Novak</code></td></tr><tr><td><code>street</code></td><td><code>Konevova</code></td></tr><tr><td><code>building_number</code></td><td><code>135</code></td></tr><tr><td><code>postal_code</code></td><td><code>13000</code></td></tr><tr><td><code>city</code></td><td><code>Praha</code></td></tr><tr><td><code>country_code</code></td><td><code>CZ</code></td></tr><tr><td><code>phone</code></td><td><code>+420777888999</code></td></tr></tbody></table><h2 id="buy-columns" tabindex="-1">Buy columns <a class="header-anchor" href="#buy-columns" aria-label="Permalink to &quot;Buy columns&quot;">​</a></h2><p>Optional on <code>mode=buy</code>:</p><table tabindex="0"><thead><tr><th>Column</th><th>Example</th><th>Notes</th></tr></thead><tbody><tr><td><code>sizes</code></td><td><code>M,L,XL</code></td><td>Preferred sizes, first available wins. Empty = random.</td></tr><tr><td><code>country_code</code></td><td><code>CZ</code></td><td>Used when URL doesn&#39;t imply a region.</td></tr></tbody></table><h2 id="delimiter" tabindex="-1">Delimiter <a class="header-anchor" href="#delimiter" aria-label="Permalink to &quot;Delimiter&quot;">​</a></h2><p>Semicolons are preferred — many product URLs contain commas. The loader auto-detects: if the header has a <code>;</code>, it splits on <code>;</code>.</p>',16)])])}const p=t(r,[["render",c]]);export{h as __pageData,p as default};
